item_id_newtype ! { # [doc = " An identifier for an `Item` whose `ItemKind` is known to be"] # [doc = " `ItemKind::Function`."] pub (crate) struct FunctionId (ItemId) where # [doc = " Convert this `ItemId` into a `FunctionId` if its associated item is a function,"] # [doc = " otherwise return `None`."] checked = as_function_id with is_function , # [doc = " Convert this `ItemId` into a `FunctionId`."] # [doc = ""] # [doc = " If this `ItemId` does not point to a function, then panic."] expected = expect_function_id , # [doc = " Convert this `ItemId` into a `FunctionId` without actually checking whether"] # [doc = " this ID actually points to a `Function`."] unchecked = as_function_id_unchecked ; }